import{_ as a,a as i,b as r,c as t,d as e,e as l}from"./chunks/9.BXFUmzx_.js";import{_ as n,b as s,a as p}from"./chunks/6.C90syIqY.js";import{_ as c,o as h,c as d,a0 as m}from"./chunks/framework.DRjqbEpm.js";const x=JSON.parse('{"title":"🚀 快速上手：安裝與首次設定","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),g={name:"guide/installation.md"};function u(b,o,f,q,k,T){return h(),d("div",null,[...o[0]||(o[0]=[m('<h1 id="🚀-快速上手-安裝與首次設定" tabindex="-1">🚀 快速上手：安裝與首次設定 <a class="header-anchor" href="#🚀-快速上手-安裝與首次設定" aria-label="Permalink to &quot;🚀 快速上手：安裝與首次設定&quot;">​</a></h1><p>歡迎來到 V-Train！這份指南會手把手帶您完成從「零」到「看影片就有進度條」的全部流程，大概只需要 3 分鐘！</p><div class="info custom-block"><p class="custom-block-title">💡 V-Train 是什麼？</p><p>V-Train 是一個 Chrome 瀏覽器擴充功能，能在您瀏覽影音網站時，自動在每部影片的縮圖底下顯示<strong>紅色觀看進度條</strong>，就像 YouTube 那樣！完全本地運作，零資料上傳。</p></div><hr><h2 id="一、安裝方式" tabindex="-1">一、安裝方式 <a class="header-anchor" href="#一、安裝方式" aria-label="Permalink to &quot;一、安裝方式&quot;">​</a></h2><h3 id="✅-方法-a-從-chrome-線上應用程式商店安裝-推薦" tabindex="-1">✅ 方法 A：從 Chrome 線上應用程式商店安裝（推薦） <a class="header-anchor" href="#✅-方法-a-從-chrome-線上應用程式商店安裝-推薦" aria-label="Permalink to &quot;✅ 方法 A：從 Chrome 線上應用程式商店安裝（推薦）&quot;">​</a></h3><p>這是最簡單、最安全的方式，適合所有人。</p><ol><li><p>點擊下方連結前往 Chrome 線上應用程式商店：</p><p><strong><a href="https://chromewebstore.google.com/detail/v-train-adaptive-video-ba/cikabjkegiefjgalfncfoehmkpmkoiaf" target="_blank" rel="noreferrer">👉 前往安裝 V-Train</a></strong></p></li><li><p>點擊頁面右上角藍色的「<strong>加到 Chrome</strong>」按鈕。</p><blockquote><p><img src="'+a+'" alt="Chrome 商店安裝頁面"></p></blockquote></li><li><p>彈出確認視窗後，點擊「<strong>新增擴充功能</strong>」。</p></li><li><p>安裝完成後，Chrome 右上角會出現 V-Train 的圖示（一個深色的 VT 標誌）。</p></li></ol><div class="tip custom-block"><p class="custom-block-title">🎉 安裝成功的確認方式</p><p>如果右上角有出現 V-Train 圖示，代表安裝成功！如果沒看到，請繼續看下面「釘選擴充功能」的步驟。</p></div><hr><h3 id="🔧-方法-b-手動安裝-開發者模式" tabindex="-1">🔧 方法 B：手動安裝（開發者模式） <a class="header-anchor" href="#🔧-方法-b-手動安裝-開發者模式" aria-label="Permalink to &quot;🔧 方法 B：手動安裝（開發者模式）&quot;">​</a></h3><p>如果您是從 GitHub 下載了原始碼、或是想測試尚未上架的版本，可以用開發者模式手動載入。</p><div class="warning custom-block"><p class="custom-block-title">⚠️ 注意</p><p>此方法適合進階使用者。從不明來源下載的擴充功能請務必謹慎，確認來源可信後再安裝。</p></div><ol><li><p>下載並解壓縮 V-Train 的原始碼資料夾到您電腦的某個位置。</p></li><li><p>在 Chrome 網址列輸入 <code>chrome://extensions</code> 並按 Enter。</p></li><li><p>點擊右上角的**「開發人員模式」**開關，將其打開。</p><blockquote><p><img src="'+i+'" alt="開啟開發人員模式"></p></blockquote></li><li><p>點擊左上角出現的**「載入未封裝項目」**按鈕。</p></li><li><p>在跳出的資料夾選擇視窗中，選取您剛才解壓縮的 V-Train 資料夾（裡面應該有 <code>manifest.json</code> 這個檔案）。</p></li><li><p>點擊「選取資料夾」，V-Train 就會出現在您的擴充功能清單中了！</p></li></ol><div class="info custom-block"><p class="custom-block-title">📌 開發者模式小提醒</p><p>以開發者模式載入的擴充功能，每次重啟 Chrome 後可能會跳出「停用開發者模式擴充功能」的警告，點擊「取消」即可繼續正常使用。</p></div><hr><h2 id="二、釘選擴充功能-讓圖示常駐工具列" tabindex="-1">二、釘選擴充功能（讓圖示常駐工具列） <a class="header-anchor" href="#二、釘選擴充功能-讓圖示常駐工具列" aria-label="Permalink to &quot;二、釘選擴充功能（讓圖示常駐工具列）&quot;">​</a></h2><p>安裝好之後，Chrome 預設會把新擴充功能「收起來」。為了方便每次使用，我們需要把 V-Train「釘出來」！</p><ol><li><p>點擊 Chrome 工具列右上角的<strong>拼圖圖案 🧩</strong>（擴充功能按鈕）。</p><blockquote><p><img src="'+r+'" alt="點擊拼圖圖案"></p></blockquote></li><li><p>在跳出的清單中，找到 <strong>V-Train Adaptive Video</strong>。</p></li><li><p>點擊右邊的<strong>圖釘圖示 📌</strong>，讓它變成藍色的「已釘選」狀態。</p><blockquote><p><img src="'+t+'" alt="釘選 V-Train 圖示"></p></blockquote></li><li><p>完成！現在 V-Train 的 VT 圖示應該會永遠顯示在工具列上了。</p></li></ol><div class="tip custom-block"><p class="custom-block-title">快速小技巧</p><p>如果您用的是 Edge 瀏覽器（也支援 Chrome 擴充功能），操作方式完全相同，一樣找工具列的拼圖圖案就可以了！</p></div><hr><h2 id="三、首次啟動-開啟控制面板" tabindex="-1">三、首次啟動：開啟控制面板 <a class="header-anchor" href="#三、首次啟動-開啟控制面板" aria-label="Permalink to &quot;三、首次啟動：開啟控制面板&quot;">​</a></h2><p>釘選完成後，就可以正式啟動 V-Train 了！</p><ol><li><p><strong>點擊工具列上的 VT 圖示</strong>。</p></li><li><p>一個黑色主題的**控制面板（Dashboard）**就會從圖示下方彈出！</p><blockquote><p><img src="'+n+'" alt="V-Train 控制面板主畫面"></p></blockquote></li></ol><p>這個面板就是 V-Train 的「指揮中心」，所有設定都在這裡操控。</p><hr><h2 id="四、授權網站-必做的第一件事" tabindex="-1">四、授權網站：必做的第一件事！ <a class="header-anchor" href="#四、授權網站-必做的第一件事" aria-label="Permalink to &quot;四、授權網站：必做的第一件事！&quot;">​</a></h2><p>V-Train 採用「<strong>按需授權</strong>」的方式，您需要主動告訴它「我允許你在這個網站上工作」。這是為了保護您的隱私——V-Train 不會在沒有您明確許可的網站上偷偷執行任何東西。</p><p>這個步驟<strong>必須在每一個想要使用 V-Train 的網站上各做一次</strong>。</p><h3 id="步驟如下" tabindex="-1">步驟如下： <a class="header-anchor" href="#步驟如下" aria-label="Permalink to &quot;步驟如下：&quot;">​</a></h3><ol><li><p>先打開您想追蹤進度的影音網站（例如：某部影片的首頁列表頁）。</p></li><li><p>點擊工具列的 VT 圖示，<strong>開啟 V-Train 控制面板</strong>。</p></li><li><p>點擊面板<strong>最上方</strong>藍色的 <strong>「授權並啟用(Authorize &amp; Enable Current Site)」</strong> 按鈕。</p><blockquote><p><img src="'+s+'" alt="授權按鈕"></p></blockquote></li><li><p>Chrome 會彈出一個系統確認視窗，詢問「是否要允許這個擴充功能讀取此網站的資料？」— 點擊**「允許」**。</p></li><li><p>授權完成後，按鈕的顏色會變成<strong>綠色</strong>，顯示「✅ 已授權(Site Authorized)（已授權）」。</p><blockquote><p><img src="'+e+'" alt="授權成功狀態"></p></blockquote></li><li><p>如果這個網站已經有內建的規則，<strong>重新整理一下頁面</strong>，您馬上就會在影片縮圖下方看到<strong>紅色進度條</strong>出現！</p></li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ 授權後沒有進度條？別擔心！</p><p>看到授權成功，但進度條還是沒出現？這很正常！這代表 V-Train 尚未「認識」這個網站。您需要用「適應引擎」來訓練它。請參考 <a href="./adaptive-engine.html">適應引擎訓練指南</a>。</p></div><hr><h2 id="五、關於預設的「手動暫停-monitoring-off-」模式" tabindex="-1">五、關於預設的「手動暫停(Monitoring Off)」模式 <a class="header-anchor" href="#五、關於預設的「手動暫停-monitoring-off-」模式" aria-label="Permalink to &quot;五、關於預設的「手動暫停(Monitoring Off)」模式&quot;">​</a></h2><p>您可能會發現，剛安裝好 V-Train 後，明明已經授權了某個網站，但還是看不到進度條？</p><p>這是因為 V-Train 在<strong>第一次安裝時，預設會開啟「手動暫停(Monitoring Off)」模式</strong>。</p><h3 id="什麼是手動暫停-monitoring-off-模式" tabindex="-1">什麼是手動暫停(Monitoring Off)模式？ <a class="header-anchor" href="#什麼是手動暫停-monitoring-off-模式" aria-label="Permalink to &quot;什麼是手動暫停(Monitoring Off)模式？&quot;">​</a></h3><p>想像一下，您偶爾想要「暫停追蹤」，不想讓 V-Train 記錄這次觀看。這時候，切換到手動暫停(Monitoring Off)就像是把 V-Train 暫時「關掉」——它不會顯示進度條，也不會記錄您的觀看進度！</p><p>**預設開啟手動暫停(Monitoring Off)**的設計，是為了讓您在安裝後有機會先熟悉面板，不會一安裝就立刻開始記錄您的一切行為。</p><h3 id="如何切換到「自動監控-monitoring-」、正式開始追蹤" tabindex="-1">如何切換到「自動監控(Monitoring)」、正式開始追蹤？ <a class="header-anchor" href="#如何切換到「自動監控-monitoring-」、正式開始追蹤" aria-label="Permalink to &quot;如何切換到「自動監控(Monitoring)」、正式開始追蹤？&quot;">​</a></h3><ol><li><p>打開 V-Train 控制面板。</p></li><li><p>找到最頂部的「<strong>狀態開關</strong>」，它目前顯示灰色指示燈的「<strong>手動暫停(Monitoring Off)</strong>」。</p></li><li><p><strong>點擊這個開關</strong>，讓它切換成綠色指示燈的「<strong>🟢 自動監控(Monitoring)</strong>」狀態。</p><blockquote><p><img src="'+p+'" alt="監控開關"></p></blockquote></li><li><p>開關變綠之後，就代表 V-Train 開始正式工作囉！<strong>重新整理頁面</strong>，進度條就會出現了！</p></li></ol><div class="tip custom-block"><p class="custom-block-title">💡 小技巧：想要隨時暫停？</p><p>兩個模式可以隨時切換！當您不想被記錄時，把開關切回「手動暫停(Monitoring Off)」；想繼續追蹤時，再切回「自動監控(Monitoring)」。操作非常彈性！</p></div><hr><h2 id="六、無痕模式注意事項" tabindex="-1">六、無痕模式注意事項 <a class="header-anchor" href="#六、無痕模式注意事項" aria-label="Permalink to &quot;六、無痕模式注意事項&quot;">​</a></h2><p>V-Train 的 manifest 設定支援無痕模式（<code>&quot;incognito&quot;: &quot;spanning&quot;</code>），但您需要手動開啟此權限。</p><div class="warning custom-block"><p class="custom-block-title">⚠️ 預設情況下，無痕視窗不可用</p><p>Chrome 出於安全考量，預設<strong>不允許</strong>任何擴充功能在無痕視窗中執行。如果您在無痕模式下打開 V-Train，可能會看到警告提示。</p></div><h3 id="如何允許-v-train-在無痕模式中使用" tabindex="-1">如何允許 V-Train 在無痕模式中使用？ <a class="header-anchor" href="#如何允許-v-train-在無痕模式中使用" aria-label="Permalink to &quot;如何允許 V-Train 在無痕模式中使用？&quot;">​</a></h3><ol><li><p>在 Chrome 網址列輸入 <code>chrome://extensions</code> 並按 Enter。</p></li><li><p>找到 <strong>V-Train Adaptive Video</strong> 並點擊「<strong>詳細資料</strong>」。</p></li><li><p>在詳細資料頁面，找到「<strong>在無痕式視窗中允許</strong>」選項。</p></li><li><p>點擊旁邊的開關，將其打開。</p><blockquote><p><img src="'+l+'" alt="允許無痕模式"></p></blockquote></li></ol><p>開啟後，V-Train 就可以在無痕視窗中正常執行了！</p><div class="info custom-block"><p class="custom-block-title">📌 無痕模式下的隱私行為</p><p>即使在無痕模式中啟用了 V-Train，您仍然可以隨時切換到「手動暫停(Monitoring Off)」來停止記錄。兩種隱私保護機制可以搭配使用。</p></div><hr><h2 id="七、常見安裝問題-q-a" tabindex="-1">七、常見安裝問題 Q&amp;A <a class="header-anchor" href="#七、常見安裝問題-q-a" aria-label="Permalink to &quot;七、常見安裝問題 Q&amp;A&quot;">​</a></h2><h3 id="❓-q-安裝後找不到-v-train-圖示怎麼辦" tabindex="-1">❓ Q：安裝後找不到 V-Train 圖示怎麼辦？ <a class="header-anchor" href="#❓-q-安裝後找不到-v-train-圖示怎麼辦" aria-label="Permalink to &quot;❓ Q：安裝後找不到 V-Train 圖示怎麼辦？&quot;">​</a></h3><p>請依照本頁「二、釘選擴充功能」的步驟，點擊工具列的拼圖圖案，手動將 V-Train 釘出來即可。</p><hr><h3 id="❓-q-點擊授權按鈕後-chrome-沒有彈出任何確認視窗" tabindex="-1">❓ Q：點擊授權按鈕後，Chrome 沒有彈出任何確認視窗？ <a class="header-anchor" href="#❓-q-點擊授權按鈕後-chrome-沒有彈出任何確認視窗" aria-label="Permalink to &quot;❓ Q：點擊授權按鈕後，Chrome 沒有彈出任何確認視窗？&quot;">​</a></h3><p>這可能是因為您目前所在的頁面是 <code>chrome://</code> 開頭的系統頁面、或是本機的 <code>file://</code> 頁面。V-Train 只能在正常的 <code>http://</code> 或 <code>https://</code> 網頁上進行授權。請先前往您想使用的影音網站，再嘗試授權。</p><hr><h3 id="❓-q-已經授權了-為什麼網站還是沒有進度條" tabindex="-1">❓ Q：已經授權了，為什麼網站還是沒有進度條？ <a class="header-anchor" href="#❓-q-已經授權了-為什麼網站還是沒有進度條" aria-label="Permalink to &quot;❓ Q：已經授權了，為什麼網站還是沒有進度條？&quot;">​</a></h3><p>請依序確認以下幾點：</p><ol><li>✅ 確認控制面板的狀態開關是「🟢 自動監控(Monitoring)」，而不是「手動暫停(Monitoring Off)」。</li><li>✅ 確認授權按鈕已變成綠色的「已授權」狀態。</li><li>✅ 重新整理頁面後再看看。</li><li>如果以上都確認過了，進度條還是沒出現——這個網站目前可能還沒有 V-Train 的內建規則。您可以使用<a href="./adaptive-engine.html">適應引擎</a>自己訓練，或到<a href="https://github.com/vtrain-labs/community-rules" target="_blank" rel="noreferrer">社群規則庫</a>查看是否有人已經分享了這個網站的規則。</li></ol><hr><h3 id="❓-q-控制面板打開後顯示的是英文-我想換成中文" tabindex="-1">❓ Q：控制面板打開後顯示的是英文，我想換成中文？ <a class="header-anchor" href="#❓-q-控制面板打開後顯示的是英文-我想換成中文" aria-label="Permalink to &quot;❓ Q：控制面板打開後顯示的是英文，我想換成中文？&quot;">​</a></h3><p>在面板頂部的右上方有一個<strong>語言選單（Language）</strong>，點開後選擇「繁體中文」即可。語言設定會即時生效！</p><hr><h3 id="❓-q-擴充功能可以在-microsoft-edge-上使用嗎" tabindex="-1">❓ Q：擴充功能可以在 Microsoft Edge 上使用嗎？ <a class="header-anchor" href="#❓-q-擴充功能可以在-microsoft-edge-上使用嗎" aria-label="Permalink to &quot;❓ Q：擴充功能可以在 Microsoft Edge 上使用嗎？&quot;">​</a></h3><p>可以！Microsoft Edge 完全支援 Chrome Web Store 的擴充功能。您可以直接用 Edge 前往 Chrome 線上應用程式商店安裝 V-Train，操作方式與 Chrome 完全相同。</p><div class="danger custom-block"><p class="custom-block-title">🚫 不支援的瀏覽器</p><p>V-Train 目前僅支援基於 Chromium 核心的瀏覽器（Chrome、Edge、Brave 等）。Firefox 及 Safari 目前<strong>不支援</strong>。</p></div><hr><h2 id="八、接下來" tabindex="-1">八、接下來… <a class="header-anchor" href="#八、接下來" aria-label="Permalink to &quot;八、接下來…&quot;">​</a></h2><p>恭喜您完成了基礎安裝！🎉 如果想深入了解每個功能，請繼續閱讀：</p><ul><li><strong><a href="./dashboard.html">控制面板詳解 →</a></strong> — 了解面板上每一個按鈕的作用</li><li><strong><a href="./adaptive-engine.html">適應引擎：訓練新網站 →</a></strong> — 讓 V-Train 支援任何影音網站</li><li><strong><a href="./pro-features.html">Pro 版功能介紹 →</a></strong> — 解鎖無限紀錄與書籤庫</li></ul>',72)])])}const C=c(g,[["render",u]]);export{x as __pageData,C as default};
